import{_ as n,o as a,c as p,a2 as l}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"04g · 蜂蜜黄油味图片关键帧提示词","description":"","frontmatter":{},"headers":[],"relativePath":"lab/shuangyu-fries/04g-honey-butter-keyframes.md","filePath":"lab/shuangyu-fries/04g-honey-butter-keyframes.md","lastUpdated":1786871523000}'),e={name:"lab/shuangyu-fries/04g-honey-butter-keyframes.md"};function t(i,s,c,o,r,d){return a(),p("div",null,[...s[0]||(s[0]=[l(`<h1 id="_04g-·-蜂蜜黄油味图片关键帧提示词" tabindex="-1">04g · 蜂蜜黄油味图片关键帧提示词 <a class="header-anchor" href="#_04g-·-蜂蜜黄油味图片关键帧提示词" aria-label="Permalink to &quot;04g · 蜂蜜黄油味图片关键帧提示词&quot;">​</a></h1><blockquote><p>对应 <a href="./03e-honey-butter-sensory-film">03e · 蜂蜜黄油味独立感官创意片</a> ｜ 7 张关键帧 ｜ 16:9 横屏</p></blockquote><div class="warning custom-block"><p class="custom-block-title">第一轮已完成，后续改用 v2</p><p>本页已用于生成 <code>images/黄油蜂蜜味/</code> 第一轮素材。实图复盘发现产品被生成成膨化棒、光带重复且断面偏面包质感；不要继续用 KF01 衍生。无包装镜头重跑请直接使用 <a href="./04i-honey-butter-v2-optimization">04i · v2 优化执行表</a>。</p></div><h2 id="使用方式" tabindex="-1">使用方式 <a class="header-anchor" href="#使用方式" aria-label="Permalink to &quot;使用方式&quot;">​</a></h2><ol><li>先生成 <strong>KF01 产品定妆帧</strong>，选定薯条脆的粗细、颜色、颗粒与质感。</li><li>后续 KF02–KF06 均上传 KF01 作为<strong>产品外观参考图</strong>，只参考食物形态，不继承背景构图。</li><li>KF04-A 与 KF04-B 使用同一参考图、同一构图和同一组手指，作为折断镜头首尾帧。</li><li>每张先生成 3–4 个版本，只选择食物结构真实、表面干爽的一张，不以特效强度作为首要标准。</li><li>所有字幕与包装均在后期加入。图片生成阶段禁止文字、logo 和虚构包装。</li></ol><h2 id="连贯性锁定" tabindex="-1">连贯性锁定 <a class="header-anchor" href="#连贯性锁定" aria-label="Permalink to &quot;连贯性锁定&quot;">​</a></h2><p>以下产品特征已完整写入每条提示词，生成时不要删改：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>同一款浅金色粗条状薯条脆，长约 8–10 厘米，宽约 1.2 厘米，四角略圆，</span></span>
<span class="line"><span>轮廓基本笔直但保留真实轻微不规则，表面粗粝酥松、干爽哑光，</span></span>
<span class="line"><span>均匀附着浅奶油黄与少量琥珀金色细小调味颗粒，断面疏松多孔。</span></span>
<span class="line"><span>它是常温杯装薯条脆，不是现炸细薯条，不冒热气。</span></span></code></pre></div><h2 id="kf01-·-甜香靠近-产品定妆帧" tabindex="-1">KF01 · 甜香靠近 / 产品定妆帧 <a class="header-anchor" href="#kf01-·-甜香靠近-产品定妆帧" aria-label="Permalink to &quot;KF01 · 甜香靠近 / 产品定妆帧&quot;">​</a></h2><p><strong>用途</strong>：镜头 01 首帧，也是全片产品外观参考图。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>高端商业食品广告摄影，真实食物质感，超现实但可信的感官奇观，电影级布光。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>纯黑影棚空间中，同一款浅金色粗条状薯条脆横向悬浮在画面中央偏上，</span></span>
<span class="line"><span>长约 8–10 厘米，宽约 1.2 厘米，四角略圆，轮廓基本笔直但保留真实轻微不规则；</span></span>
<span class="line"><span>表面粗粝酥松、干爽哑光，均匀附着浅奶油黄与少量琥珀金色细小调味颗粒，</span></span>
<span class="line"><span>右端轻微朝向镜头，能看见一点疏松多孔的真实断面。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>一道半透明琥珀金色光带从画面左后方靠近，在薯条脆后方形成柔和弧线，</span></span>
<span class="line"><span>光带表达蜂蜜般温暖缓慢的甜香，但它只是光，不是液体，</span></span>
<span class="line"><span>不接触食物，没有滴落、拉丝、飞溅或黏稠质感；</span></span>
<span class="line"><span>一道窄幅暖金硬光扫亮产品上缘与表面裂纹，下方保留深黑负空间，</span></span>
<span class="line"><span>画面安静、克制、有爆发前的张力，主体占画面宽度约 55%。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>100mm macro lens，产品超微距，浅景深 f/2.0，轻微低机位，</span></span>
<span class="line"><span>暖金侧逆光，黑金高反差，真实商业食品摄影，轻微胶片颗粒，</span></span>
<span class="line"><span>自然色彩，不过度锐化、不过度饱和，16:9 横屏，高清细节。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>禁止：包装、文字、logo、水印、人物、手、番茄、红色调味粉、蜂巢、蜜蜂、蜂蜜罐、</span></span>
<span class="line"><span>真实黄油块、蜂蜜液体、黄油液体、黏稠拉丝、油滴、表面浮油、油腻反光、蒸汽、</span></span>
<span class="line"><span>深褐色、焦黑、普通细薯条、弯曲软塌、薯片、饼干棒、面包、爆米花、</span></span>
<span class="line"><span>火焰、烟雾、玻璃、宝石、金属颗粒、塑料感、卡通、插画。</span></span></code></pre></div><p><strong>验收重点</strong>：粗条形态正确；右端断面真实；光带不被误画成蜂蜜液体。</p><h2 id="kf02-·-黄油融光" tabindex="-1">KF02 · 黄油融光 <a class="header-anchor" href="#kf02-·-黄油融光" aria-label="Permalink to &quot;KF02 · 黄油融光&quot;">​</a></h2><p><strong>用途</strong>：镜头 02 主关键帧。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>使用上传的 KF01 只作为薯条脆外观参考，严格保持同一根产品的粗细、长度、</span></span>
<span class="line"><span>浅金色、四角略圆、表面粗粝酥松与浅奶油黄调味颗粒；更换为以下全新场景和构图。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>高端商业食品广告摄影，通透明亮的奶油白影棚空间中，</span></span>
<span class="line"><span>同一根浅金色粗条状薯条脆从画面左下斜向右上悬浮穿行，</span></span>
<span class="line"><span>表面干爽哑光，轮廓清楚，边缘被柔和暖光勾亮；</span></span>
<span class="line"><span>后方展开一层宽阔、半透明的奶油黄色柔光幕，像温暖香气在空气里舒展，</span></span>
<span class="line"><span>光幕具有轻盈丝绸般的视觉流动，但没有实体材质，不是布料，也不是黄油液体，</span></span>
<span class="line"><span>不接触、不覆盖食物；前景有两三颗极小琥珀色食物调味颗粒虚化掠过，</span></span>
<span class="line"><span>背景由奶油白自然过渡到浅黄油色，明亮、柔软、有空气感。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>85mm lens，中近景，浅景深 f/2.8，自然柔光加奶油金侧逆光，</span></span>
<span class="line"><span>真实商业食品摄影，轻微胶片颗粒，自然色彩，16:9 横屏，高清细节。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>禁止：改变参考产品外观、增加第二根产品、包装、文字、logo、水印、人物、手、</span></span>
<span class="line"><span>番茄、红色、蜂巢、蜜蜂、蜂蜜罐、真实黄油块、黄色液体、蜂蜜滴淋、黄油包裹、</span></span>
<span class="line"><span>黏稠拉丝、油滴、油光、蒸汽、深褐色、焦黑、普通细薯条、薯片、饼干棒、</span></span>
<span class="line"><span>布料褶皱、塑料薄膜、火焰、烟雾、金属粒子、卡通、插画。</span></span></code></pre></div><p><strong>验收重点</strong>：仍是 KF01 的同一款产品；光幕是无实体的柔光，不像布或液体。</p><h2 id="kf03-·-风味落脆" tabindex="-1">KF03 · 风味落脆 <a class="header-anchor" href="#kf03-·-风味落脆" aria-label="Permalink to &quot;KF03 · 风味落脆&quot;">​</a></h2><p><strong>用途</strong>：镜头 03 主关键帧。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>使用上传的 KF01 只作为薯条脆外观参考，保持相同粗细、颜色、干爽哑光质地与调味颗粒。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>高端商业食品广告超微距摄影，一根同款浅金色粗条状薯条脆从画面左下延伸至右上，</span></span>
<span class="line"><span>镜头贴近其表面，清楚看见真实粗粝纹理、微小裂纹与酥松边缘；</span></span>
<span class="line"><span>奶油黄与琥珀金两种真实细小食物调味颗粒从画面上方沿疏松螺旋轨迹落下，</span></span>
<span class="line"><span>少量颗粒刚刚触碰表面，在凹凸处自然弹起或停住，分布均匀克制；</span></span>
<span class="line"><span>颗粒具有真实粉末与小颗粒质感，不发光，不像金粉或珠宝，</span></span>
<span class="line"><span>没有任何液体、油滴或黏稠物；前景、中景、后景各有少量颗粒形成纵深，</span></span>
<span class="line"><span>背景为干净奶油白到浅琥珀金的柔和过渡。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>100mm macro lens，1000fps 高速摄影定格感，极浅景深 f/2.0，略微俯视，</span></span>
<span class="line"><span>焦点落在中央一颗琥珀色调味颗粒及其接触位置，侧逆光照亮颗粒边缘，</span></span>
<span class="line"><span>真实商业食品摄影，极高纹理细节，16:9 横屏。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>禁止：改变参考产品外观、包装、文字、logo、水印、人物、手、番茄、红色调味粉、</span></span>
<span class="line"><span>蜂巢、蜜蜂、蜂蜜罐、黄油块、蜂蜜液体、黄色酱汁、黏稠拉丝、油滴、浮油、</span></span>
<span class="line"><span>发光金粉、金属粉、玻璃珠、宝石、爆炸、烟雾、深褐色、焦黑、</span></span>
<span class="line"><span>普通细薯条、薯片、饼干棒、塑料感、卡通、插画。</span></span></code></pre></div><p><strong>验收重点</strong>：调味颗粒必须像食物；颗粒附着但产品不显湿润。</p><h2 id="kf04-a-·-一折即脆-首帧" tabindex="-1">KF04-A · 一折即脆 / 首帧 <a class="header-anchor" href="#kf04-a-·-一折即脆-首帧" aria-label="Permalink to &quot;KF04-A · 一折即脆 / 首帧&quot;">​</a></h2><p><strong>用途</strong>：镜头 04 首帧。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>使用上传的 KF01 作为薯条脆外观参考，保持同一款浅金色粗条状产品的尺寸、</span></span>
<span class="line"><span>颜色、干爽粗粝表面与浅奶油黄调味颗粒。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>高端商业食品广告微距摄影，纯黑影棚背景中，</span></span>
<span class="line"><span>一根完整未断的浅金色粗条状薯条脆水平位于画面中央，</span></span>
<span class="line"><span>左手拇指与食指只捏住产品左端，右手拇指与食指只捏住产品右端，</span></span>
<span class="line"><span>两组手指从画面左右边缘自然进入，结构正确、指甲干净、皮肤纹理真实，</span></span>
<span class="line"><span>手指之间保留足够距离，正在施力前一瞬，薯条脆仍然笔直完整；</span></span>
<span class="line"><span>产品中央是画面最清晰区域，表面裂纹、粗粝质地和调味颗粒清楚可见，</span></span>
<span class="line"><span>一道强逆光从产品正后方照出暖金轮廓，背景纯黑，下方保留少量负空间。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>100mm macro lens，正侧面特写，固定机位，浅景深 f/2.8，</span></span>
<span class="line"><span>强逆光加克制正面补光，真实肤色与真实商业食品摄影，16:9 横屏，高清细节。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>禁止：产品已经断裂、产品明显弯曲、碎屑、额外手指、超过两只手、完整手掌、</span></span>
<span class="line"><span>手指交叉、指甲油、首饰、包装、文字、logo、水印、番茄、红色调味粉、</span></span>
<span class="line"><span>蜂蜜、黄油块、液体、油光、蒸汽、普通细薯条、薯片、面包断面、</span></span>
<span class="line"><span>塑料感、卡通、插画。</span></span></code></pre></div><h2 id="kf04-b-·-一折即脆-尾帧" tabindex="-1">KF04-B · 一折即脆 / 尾帧 <a class="header-anchor" href="#kf04-b-·-一折即脆-尾帧" aria-label="Permalink to &quot;KF04-B · 一折即脆 / 尾帧&quot;">​</a></h2><p><strong>用途</strong>：镜头 04 尾帧，必须与 KF04-A 构图匹配。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>使用上传的 KF04-A 作为严格构图与手部参考。保持相同画幅、固定机位、焦距、</span></span>
<span class="line"><span>黑色背景、两组手指身份、手指位置、肤色、灯光方向与产品尺度；</span></span>
<span class="line"><span>只把完整薯条脆改为刚刚断裂后的状态。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>高端商业食品广告超高速摄影定格：同一根浅金色粗条状薯条脆刚从正中央干净折断，</span></span>
<span class="line"><span>左手两指仍捏住左段，右手两指仍捏住右段，两段仅向左右分开约 2 厘米；</span></span>
<span class="line"><span>两个参差自然的断口都略微朝向镜头，清晰可见疏松多孔的酥松结构，</span></span>
<span class="line"><span>孔洞大小不规则但真实，不像面包、海绵或蜂巢；</span></span>
<span class="line"><span>少量真实金色食物碎屑从断裂点向前方与左右飞出，碎屑大小有层次、边缘不规则，</span></span>
<span class="line"><span>受真实重力和惯性影响；强逆光点亮部分孔洞与碎屑边缘，断裂点是全画面最亮区域。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>100mm macro lens，1000fps 超高速摄影，正侧面特写，固定机位，浅景深 f/2.8，</span></span>
<span class="line"><span>强逆光加窄幅暖金轮廓光，真实肤色，真实商业食品摄影，16:9 横屏，高清细节。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>禁止：改变手指数量与位置、改变机位、改变产品粗细和颜色、增加完整手掌、</span></span>
<span class="line"><span>畸形手、额外手指、巨大爆炸、密集粉尘、烟花、玻璃、金属、火焰、烟雾、</span></span>
<span class="line"><span>面包断面、海绵断面、规则蜂巢、液体、油光、包装、文字、logo、水印、卡通、插画。</span></span></code></pre></div><p><strong>首尾帧共同验收</strong>：手指位置与机位一致；只允许“完整产品 → 中央断裂”发生变化。</p><h2 id="kf05-·-咔嚓连击-高潮定格" tabindex="-1">KF05 · 咔嚓连击 / 高潮定格 <a class="header-anchor" href="#kf05-·-咔嚓连击-高潮定格" aria-label="Permalink to &quot;KF05 · 咔嚓连击 / 高潮定格&quot;">​</a></h2><p><strong>用途</strong>：镜头 05 节奏高潮的视觉定帧；实际视频仍拆成三个动作生成。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>使用上传的 KF01 作为全部薯条脆的外观参考，画面内每一根都必须保持相同粗细、</span></span>
<span class="line"><span>浅金色、四角略圆、干爽粗粝表面与浅奶油黄调味颗粒。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>明亮奶油白影棚空间中，三组薯条脆动作沿左下到右上的斜线形成清晰节奏：</span></span>
<span class="line"><span>左后方一根薯条脆刚落在台面，弹起三四颗真实碎屑；</span></span>
<span class="line"><span>画面中央两根薯条脆在空中轻轻交错相碰，保持完整；</span></span>
<span class="line"><span>右前方一根薯条脆刚从中央断裂，两段朝镜头飞近，断面疏松多孔；</span></span>
<span class="line"><span>三个动作彼此分离、不重叠，每个动作点周围只有一圈由真实食物碎屑构成的疏松声波，</span></span>
<span class="line"><span>声波由左到右逐渐变大，仍然是可辨认的食物碎屑，不是抽象光圈；</span></span>
<span class="line"><span>暖奶油白背景配克制琥珀金弧形光影，画面有速度、纵深和连续三次脆响的节拍感。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>50mm lens，中近景，轻微低机位，前中后景层次明确，</span></span>
<span class="line"><span>高速摄影定格感，暖金侧逆光加柔和顶光，真实商业食品摄影，</span></span>
<span class="line"><span>自然色彩，不过度锐化、不过度饱和，16:9 横屏，高清细节。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>禁止：不同形态或颜色的产品、手、人物、包装、文字、logo、水印、番茄、红色、</span></span>
<span class="line"><span>蜂巢、蜜蜂、蜂蜜液体、黄油块、油滴、油光、普通细薯条、薯片、饼干棒、</span></span>
<span class="line"><span>产品互相融合、无重力漂浮、巨大爆炸、烟花、玻璃、金属声波、火焰、烟雾、</span></span>
<span class="line"><span>深褐色、焦黑、塑料感、卡通、插画。</span></span></code></pre></div><p><strong>验收重点</strong>：三组动作能一眼按左、中、右读出；碎屑声波不能变成金属特效。</p><h2 id="kf06-·-产品落版-空景底图" tabindex="-1">KF06 · 产品落版 / 空景底图 <a class="header-anchor" href="#kf06-·-产品落版-空景底图" aria-label="Permalink to &quot;KF06 · 产品落版 / 空景底图&quot;">​</a></h2><p><strong>用途</strong>：镜头 06 落版背景；后期合成蜂蜜黄油味终稿包装。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>使用上传的 KF01 作为薯条脆外观参考。生成一张不含任何包装、不含文字的高端食品广告空景底图。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>暖奶油白影棚台面与同色无缝背景，画面右侧黄金分割区域为空，</span></span>
<span class="line"><span>预留一只圆柱形杯装产品完整直立的位置，预留区域宽约画面 24%、高约画面 62%，</span></span>
<span class="line"><span>该区域内不放置任何物体、假包装、轮廓或文字；</span></span>
<span class="line"><span>三根同款浅金色粗条状薯条脆在预留杯位前方形成稳定放射构图，</span></span>
<span class="line"><span>一根横向置于台面，一根斜向靠近预留杯位但不悬空，一根位于右前方形成景深，</span></span>
<span class="line"><span>表面均匀附着浅奶油黄与少量琥珀金调味颗粒，始终干爽哑光；</span></span>
<span class="line"><span>少量真实金色食物碎屑从预留杯底位置向外形成一圈克制的疏松声波；</span></span>
<span class="line"><span>背景有柔和琥珀金弧形光影，画面左侧保留约三分之一干净负空间用于后期品牌文案，</span></span>
<span class="line"><span>台面在预留杯位下方保留自然接触阴影区域，整体稳定、高级、明亮、有食欲。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>50mm lens，商业食品英雄镜头，中近景，轻微低机位，浅景深 f/4，</span></span>
<span class="line"><span>暖金硬光从右后方勾勒产品边缘，正面大面积柔光，真实摄影，</span></span>
<span class="line"><span>轻微胶片颗粒，自然色彩，16:9 横屏，高清细节。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>禁止：任何包装、杯子、罐子、标签、文字、logo、水印、人物、手、番茄、红色、</span></span>
<span class="line"><span>蜂巢、蜜蜂、蜂蜜罐、黄油块、蜂蜜液体、黄色酱汁、油滴、油光、蒸汽、</span></span>
<span class="line"><span>普通细薯条、薯片、饼干棒、产品悬浮、金属声波、发光圆环、火焰、烟雾、</span></span>
<span class="line"><span>深褐色、焦黑、塑料感、卡通、插画。</span></span></code></pre></div><p><strong>后期合成要求</strong>：只使用客户确认的蜂蜜黄油味终稿包装实拍或渲染图；匹配杯底接触阴影、透视、色温与景深，不用番茄味包装改色。</p><h2 id="生成顺序与选片" tabindex="-1">生成顺序与选片 <a class="header-anchor" href="#生成顺序与选片" aria-label="Permalink to &quot;生成顺序与选片&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">顺序</th><th>关键帧</th><th style="text-align:right;">每轮建议</th><th>选片标准</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td>KF01</td><td style="text-align:right;">4 张</td><td>产品定妆正确，光带不是液体</td></tr><tr><td style="text-align:right;">2</td><td>KF04-A</td><td style="text-align:right;">4 张</td><td>手部自然，产品完整且水平</td></tr><tr><td style="text-align:right;">3</td><td>KF04-B</td><td style="text-align:right;">4 张</td><td>与首帧一致，断面和碎屑真实</td></tr><tr><td style="text-align:right;">4</td><td>KF03</td><td style="text-align:right;">3 张</td><td>颗粒像食物，表面保持干爽</td></tr><tr><td style="text-align:right;">5</td><td>KF02</td><td style="text-align:right;">3 张</td><td>光幕柔和且没有实体感</td></tr><tr><td style="text-align:right;">6</td><td>KF05</td><td style="text-align:right;">4 张</td><td>三段动作层次清晰</td></tr><tr><td style="text-align:right;">7</td><td>KF06</td><td style="text-align:right;">3 张</td><td>包装预留区和文案区足够干净</td></tr></tbody></table><h2 id="全组验收" tabindex="-1">全组验收 <a class="header-anchor" href="#全组验收" aria-label="Permalink to &quot;全组验收&quot;">​</a></h2><ul><li>[ ] 7 张均为 16:9 横屏，产品外观、粗细与色温一致</li><li>[ ] 产品是粗条状杯装薯条脆，不是现炸细薯条、薯片或饼干棒</li><li>[ ] 调味颗粒为浅奶油黄与少量琥珀金，不出现番茄红</li><li>[ ] 风味特效不接触、不浸泡产品，表面无液体、浮油与黏稠拉丝</li><li>[ ] KF04-A/B 的机位、手指和产品尺度一致，只改变断裂状态</li><li>[ ] 碎屑像真实食物并遵循重力，不像玻璃、金属、烟花或抽象发光粒子</li><li>[ ] 所有图片无文字、logo、水印和生成包装</li><li>[ ] KF06 的杯装产品区与左侧文案区均留空，可直接进入后期合成</li></ul><hr><p><strong>导演执行稿</strong> ← <a href="./03e-honey-butter-sensory-film">03e · 蜂蜜黄油味独立感官创意片</a></p>`,41)])])}const u=n(e,[["render",t]]);export{g as __pageData,u as default};
